//! Window and mel filterbank against librosa 1.0 reference values (PRD 9.1).
//! tests/data/librosa_reference.txt is generated by `librosa.filters.mel(..., htk=False,
//! norm="slaney")` and `librosa.filters.get_window("hann", 2048, fftbins=True)`.

use resonance_dsp::mel::{hz_to_mel, MelBank};
use resonance_dsp::window::hann;

const REFERENCE: &str = include_str!("data/librosa_reference.txt");

struct Bank {
    sr: f32,
    n_fft: usize,
    fmax: f32,
    rows: Vec<(usize, Vec<f32>)>,
}

fn parse() -> (Vec<Bank>, Vec<(f64, f64)>, Vec<f64>) {
    let mut banks: Vec<Bank> = Vec::new();
    let mut mels = Vec::new();
    let mut hann_vals = Vec::new();
    for line in REFERENCE.lines() {
        let parts: Vec<&str> = line.split_whitespace().collect();
        match parts[0] {
            "bank" => banks.push(Bank {
                sr: parts[1].parse().unwrap(),
                n_fft: parts[2].parse().unwrap(),
                fmax: parts[5].parse().unwrap(),
                rows: Vec::new(),
            }),
            "hz_to_mel" => mels.push((parts[1].parse().unwrap(), parts[2].parse().unwrap())),
            "hann2048" => {
                hann_vals = vec![
                    parts[2].parse().unwrap(),
                    parts[4].parse().unwrap(),
                    parts[6].parse().unwrap(),
                ]
            }
            _ => {
                let start = parts[0].parse().unwrap();
                let w = parts[1..].iter().map(|v| v.parse().unwrap()).collect();
                banks.last_mut().unwrap().rows.push((start, w));
            }
        }
    }
    (banks, mels, hann_vals)
}

#[test]
fn hann_matches_reference() {
    let (_, _, h) = parse();
    let w = hann(2048);
    let sum: f64 = w.iter().map(|&v| v as f64).sum();
    assert!((sum - h[0]).abs() < 1e-3, "sum {sum}");
    assert!((w[1] as f64 - h[1]).abs() < 1e-9);
    assert!((w[512] as f64 - h[2]).abs() < 1e-7);
}

#[test]
fn hann_overlap_add_is_constant_at_quarter_hop() {
    let n = 2048;
    let w = hann(n);
    let hop = n / 4;
    let sums: Vec<f32> = (0..hop)
        .map(|i| (0..4).map(|k| w[i + k * hop]).sum())
        .collect();
    for s in &sums {
        assert!((s - 2.0).abs() < 1e-5);
    }
}

#[test]
fn mel_scale_matches_reference() {
    let (_, mels, _) = parse();
    for (hz, mel) in mels {
        assert!((hz_to_mel(hz) - mel).abs() < 1e-6, "hz {hz}");
    }
}

#[test]
fn filterbank_matches_librosa() {
    let (banks, _, _) = parse();
    assert_eq!(banks.len(), 2);
    for b in banks {
        let ours = MelBank::new(b.sr, b.n_fft, 64, 30.0, b.fmax);
        assert_eq!(ours.len(), b.rows.len());
        for (m, ((start, weights), f)) in b.rows.iter().zip(&ours.filters).enumerate() {
            assert_eq!(f.start, *start, "sr {} filter {m} start", b.sr);
            assert_eq!(
                f.weights.len(),
                weights.len(),
                "sr {} filter {m} width",
                b.sr
            );
            for (x, y) in f.weights.iter().zip(weights) {
                assert!(
                    (x - y).abs() <= 1e-6 * y.abs().max(1e-3),
                    "filter {m}: {x} vs {y}"
                );
            }
        }
    }
}

#[test]
fn slaney_filters_have_unit_area_in_hz() {
    let sr = 44_100.0;
    let n_fft = 8192; // fine resolution so the Riemann sum is accurate
    let bank = MelBank::new(sr, n_fft, 64, 30.0, 16_000.0);
    let df = sr / n_fft as f32;
    for (m, f) in bank.filters.iter().enumerate().skip(4) {
        let area: f32 = f.weights.iter().sum::<f32>() * df;
        assert!((area - 1.0).abs() < 0.03, "filter {m} area {area}");
    }
}
